import { getIsoBaseMediaChildren } from '../get-children';
export const parseMoov = async ({ offset, size, state, }) => {
    const children = await getIsoBaseMediaChildren({
        state,
        size: size - 8,
    });
    return {
        offset,
        boxSize: size,
        type: 'moov-box',
        children,
    };
};
